"""Call half of the `complexity_infer` expression walker: builtins, methods, heaps, user calls.

A call to a function already on the stack is a recursive call: it is recorded as a `RecSite`
(priced at nothing) and `Analyzer.run_function` prices the recursion once the body is done.
"""
from __future__ import annotations

import ast
from dataclasses import dataclass, replace

from complexity_cost import ONE, Cost, mul
from complexity_model import (CONTAINERS, SELF_NAMES, ZERO, Abstain, Frame, Pair, Val, callee_name,
                              is_linear, is_num, log_cost)

O1_BUILTINS = frozenset("len abs int float str bool ord chr isinstance round divmod print".split())
MODULES = frozenset({"heapq", "math", "collections"})
MATH_FUNCS = frozenset("floor ceil sqrt log log2 gcd isqrt".split())
HEAP_FUNCS = frozenset({"heappush", "heappop", "heapify"})


@dataclass(frozen=True)
class RecSite:
    """A recursive call: where it is, whether it is outside every loop, and the scope it sits in."""
    call: ast.Call
    flat: bool
    env: dict
    skip_self: bool


class CallMixin:
    def call(self, e: ast.Call, fr: Frame) -> Pair:
        args = self.fold(self.expr(a, fr) for a in (*e.args, *(k.value for k in e.keywords)))
        name, func = callee_name(e), e.func
        if isinstance(func, ast.Name):
            local = fr.fns.get(name) or self.module_fns.get(name)
            if local is not None:
                return args.then(self.user_call(local, e, fr, False))
            return args.then(self.builtin(name, e, fr))
        if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name):
            if func.value.id in SELF_NAMES and name in self.methods:
                return args.then(self.user_call(self.methods[name], e, fr, True))
            if func.value.id in MODULES:
                return args.then(self.builtin(name, e, fr))
            return args.then(self.method(name, e, func.value, fr))
        raise Abstain("unknown call")

    def user_call(self, f: ast.FunctionDef, call: ast.Call, fr: Frame, skip_self: bool) -> Pair:
        if f.name in fr.stack:
            if fr.stack[-1] != f.name:
                raise Abstain(f"mutual recursion through {f.name}")
            self.rec_sites.setdefault(f.name, []).append(
                RecSite(call, fr.loops == ONE, dict(fr.env), skip_self))
            return ZERO
        params = [a.arg for a in f.args.args][1 if skip_self else 0:]
        given = dict(zip(params, call.args))
        given.update({k.arg: k.value for k in call.keywords if k.arg})
        env = {k: replace(v, owned=False) if v.kind in CONTAINERS else v for k, v in fr.env.items()}
        for p in params:
            env.pop(p, None)
            val = self.infer_val(given[p], fr) if p in given else None
            if val is not None:
                env[p] = replace(val, owned=False) if val.kind in CONTAINERS else val
        callee = Frame(env, dict(fr.fns), (*fr.stack, f.name), ONE, fr.outputs)
        return self.run_function(f, callee)

    def builtin(self, name: str, e: ast.Call, fr: Frame) -> Pair:
        args = e.args
        if name in O1_BUILTINS or name in MATH_FUNCS or name in ("defaultdict", "OrderedDict"):
            return ZERO
        if name in ("min", "max"):
            if len(args) == 1:
                return Pair(self.size_of(args[0], fr), ONE)
            if any(self.is_container(a, fr) for a in args):
                raise Abstain("min/max of containers")
            return ZERO
        if name in ("sum", "any", "all") and len(args) == 1:
            return Pair(self.size_of(args[0], fr), ONE)
        if name == "sorted" and args:
            n = self.size_of(args[0], fr)
            return Pair(mul(n, log_cost(n)), n)
        if name in ("list", "set", "frozenset", "tuple", "dict", "deque", "Counter"):
            n = self.size_of(args[0], fr) if args else ONE
            return Pair(n, n)
        if name in ("reversed", "enumerate", "zip", "range", "iter"):
            return ZERO
        if name in HEAP_FUNCS:
            return self.heap(name, e, fr)
        raise Abstain(f"unknown call {name}")

    def heap(self, name: str, e: ast.Call, fr: Frame) -> Pair:
        target = e.args[0] if e.args else None
        val = fr.env.get(target.id) if isinstance(target, ast.Name) else None
        if val is None or val.kind != "seq":
            raise Abstain("heap is not a known list")
        if name == "heapify":
            n = self.size_of(target, fr)
            self.record_heap(target.id, n)
            return Pair(n, ONE)
        if name == "heappush":
            if fr.loops is None:
                raise Abstain("push in an unbounded loop")
            self.record_heap(target.id, fr.loops)
            return Pair(log_cost(fr.loops), self.growth(target.id, val, ONE, fr, e.args[1:]))
        if target.id not in self.heap_bounds:
            raise Abstain("pop before the heap's size is known")
        return Pair(log_cost(self.heap_bounds[target.id]), ONE)

    def record_heap(self, name: str, bound: Cost) -> None:
        if self.heap_bounds.setdefault(name, bound) != bound:
            raise Abstain("heap bound is not clear")

    def growth(self, name: str, val: Val, amount: Cost, fr: Frame, elems=()) -> Cost | None:
        """Space a container gains over the loops around this site; None = cannot tell."""
        if name in fr.outputs:
            return ONE
        if name in self.carried:
            return amount if fr.loops == ONE else None  # one cell per call; depth multiplies it
        if name in self.shrunk or not val.owned or fr.loops is None or any(
                self.retains_container(x, fr) for x in elems):
            return None
        if val.kind != "seq" and not is_linear(fr.loops):
            return None  # adds repeat keys, so a set or dict is only sized by a single loop
        return mul(fr.loops, amount)

    def method(self, name: str, e: ast.Call, base: ast.Name, fr: Frame) -> Pair:
        val, args = fr.env.get(base.id), e.args
        if val is None or val.kind not in CONTAINERS:
            raise Abstain(f"method {name} on an unknown receiver")
        if name in ("append", "appendleft", "add") and val.kind in ("seq", "set"):
            return Pair(ONE, self.growth(base.id, val, ONE, fr, args))
        if name == "setdefault" and val.kind == "dict":
            return Pair(ONE, self.growth(base.id, val, ONE, fr, args[1:]))
        if name in ("extend", "update") and args:
            n = self.size_of(args[0], fr)
            return Pair(n, self.growth(base.id, val, n, fr))
        if name in ("pop", "popleft", "get", "discard", "remove", "keys", "values", "items"):
            return self.cheap_method(name, e, val)
        if name in ("sort", "copy", "reverse", "count", "index") and val.kind == "seq" and val.size is not None:
            n = val.size
            return Pair(mul(n, log_cost(n)) if name == "sort" else n,
                        n if name in ("sort", "copy") else ONE)
        raise Abstain(f"unknown method {name}")

    @staticmethod
    def cheap_method(name: str, e: ast.Call, val: Val) -> Pair:
        args = e.args
        from_end = len(args) == 1 and isinstance(args[0], ast.UnaryOp) and is_num(args[0].operand, 1)
        if name in ("pop", "popleft") and val.kind == "seq" and args and not from_end:
            raise Abstain("pop from the middle of a list")
        if name in ("discard", "remove") and val.kind == "seq":
            if val.size is None:
                raise Abstain("remove from an unsized list")
            return Pair(val.size, ONE)
        return ZERO

"""Cost algebra for `complexity_infer`: a cost is a sum of monomials over symbols and their logs.

A factor is `(symbol, polynomial exponent, log exponent)`, a monomial is a set of factors with
distinct symbols, and a cost is a set of monomials with no term dominated by another.
`n log n + n log R` stays two terms (neither dominates the other); `n + n log n` collapses.

An exponential `3^k` (constant integer base >= 2, one symbol) is the factor `("3^k", 1, 0)`: its
name carries the base and the symbol, and sits next to any plain factor of that symbol (`k·3^k`
keeps both). Per symbol the larger base dominates outright; equal bases compare (poly, log).
Multiplying two bases on one symbol multiplies the bases.

`canonical_labels` parses each complexity-pool label into a cost once, so the analyzer picks the
label whose canonical form equals the inferred one instead of formatting strings itself. A label
outside the supported grammar (`α(n)`, `kⁿ`, `min(..)`, `!`) is left out, so it is never inferred.

Stdlib only: the site runs this in Pyodide.
"""
from __future__ import annotations

import re

Factor = tuple[str, int, int]
Mono = frozenset[Factor]
Cost = frozenset[Mono]

ONE: Cost = frozenset({frozenset()})
_TOKEN = re.compile(r"log|min|max|[A-Za-z]|\d+|[²³]|[()+·]|\S")
_SUPERSCRIPTS = {"²": 2, "³": 3}
MIN_BASE = 2


def sym(name: str) -> Cost:
    return frozenset({frozenset({(name, 1, 0)})})


def _exp_name(base: int, symbol: str) -> str:
    return f"{base}^{symbol}"


def _exp_parts(name: str) -> tuple[int, str] | None:
    """`"3^k"` -> `(3, "k")`; None for a plain symbol."""
    base, caret, symbol = name.partition("^")
    return (int(base), symbol) if caret else None


def exp_of_cost(base: int, cost: Cost) -> Cost:
    """`base ** cost` for a single-symbol linear cost (`k` -> `3^k`); anything else raises ValueError."""
    if base >= MIN_BASE and len(cost) == 1:
        (mono,) = cost
        if len(mono) == 1:
            ((name, poly, logs),) = mono
            if (poly, logs) == (1, 0) and _exp_parts(name) is None:
                return frozenset({frozenset({(_exp_name(base, name), 1, 0)})})
    raise ValueError("exponent of a non-linear single-symbol cost")


def _mono_mul(a: Mono, b: Mono) -> Mono:
    exponents: dict[str, tuple[int, int]] = {}
    bases: dict[str, int] = {}
    for name, poly, logs in (*a, *b):
        parts = _exp_parts(name)
        if parts:
            bases[parts[1]] = bases.get(parts[1], 1) * parts[0]
            continue
        old_poly, old_logs = exponents.get(name, (0, 0))
        exponents[name] = (old_poly + poly, old_logs + logs)
    plain = {(name, poly, logs) for name, (poly, logs) in exponents.items()}
    return frozenset(plain | {(_exp_name(base, name), 1, 0) for name, base in bases.items()})


def _dominates(big: Mono, small: Mono) -> bool:
    """`big` grows at least as fast as `small` in every symbol. Per symbol the exponential base
    decides first (a missing base is 1); only equal bases compare (poly, log)."""
    big_plain, big_bases = _split(big)
    small_plain, small_bases = _split(small)
    for symbol in small_plain.keys() | small_bases.keys():
        big_base, small_base = big_bases.get(symbol, 1), small_bases.get(symbol, 1)
        if big_base < small_base:
            return False
        if big_base == small_base and big_plain.get(symbol, (0, 0)) < small_plain.get(symbol, (0, 0)):
            return False
    return True


def _split(mono: Mono) -> tuple[dict[str, tuple[int, int]], dict[str, int]]:
    """A monomial's plain `(poly, log)` and exponential base, each by symbol."""
    plain: dict[str, tuple[int, int]] = {}
    bases: dict[str, int] = {}
    for name, poly, logs in mono:
        parts = _exp_parts(name)
        if parts:
            bases[parts[1]] = parts[0]
        else:
            plain[name] = (poly, logs)
    return plain, bases


def _simplify(monos: set[Mono] | frozenset[Mono]) -> Cost:
    return frozenset(m for m in monos
                     if not any(o != m and _dominates(o, m) for o in monos))


def add(a: Cost, b: Cost) -> Cost:
    return _simplify(a | b)


def mul(a: Cost, b: Cost) -> Cost:
    return _simplify({_mono_mul(x, y) for x in a for y in b})


def log_of_cost(cost: Cost) -> Cost:
    """log of a single-symbol linear cost (`n` -> `log n`); a constant stays constant.
    Anything else (a product, a sum, a power) has no label-able log, so it raises ValueError."""
    if cost == ONE:
        return ONE
    if len(cost) == 1:
        (mono,) = cost
        if len(mono) == 1:
            ((name, poly, logs),) = mono
            if (poly, logs) == (1, 0) and _exp_parts(name) is None:
                return frozenset({frozenset({(name, 0, 1)})})
    raise ValueError("log of a non-linear single-symbol cost")


class _LabelParser:
    """expr := term ('+' term)* ; term := factor ('·'? factor)* ;
    factor := 'log' symbol | digits ('^' symbol | 'ⁿ') | atom power? ; atom := symbol | '(' expr ')'.
    Raises ValueError on anything outside that grammar."""

    def __init__(self, text: str) -> None:
        self.tokens = _TOKEN.findall(text)
        self.pos = 0

    def peek(self) -> str | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def take(self) -> str:
        token = self.peek()
        if token is None:
            raise ValueError("unexpected end")
        self.pos += 1
        return token

    def parse(self) -> Cost:
        cost = self.expr()
        if self.peek() is not None:
            raise ValueError(f"trailing {self.peek()!r}")
        return cost

    def expr(self) -> Cost:
        cost = self.term()
        while self.peek() == "+":
            self.take()
            cost = add(cost, self.term())
        return cost

    def term(self) -> Cost:
        cost = self.factor()
        while self.peek() is not None and self.peek() not in ("+", ")"):
            if self.peek() == "·":
                self.take()
            cost = mul(cost, self.factor())
        return cost

    def exponential(self, base: int) -> Cost:
        """`3^k` or `2ⁿ` (a digit base, so `kⁿ` never reaches here)."""
        marker = self.take()
        symbol = "n" if marker == "ⁿ" else self.take() if marker == "^" else ""
        if base < MIN_BASE or not (symbol.isascii() and symbol.isalpha()) or symbol in (
                "log", "min", "max"):
            raise ValueError("unsupported exponential")
        return frozenset({frozenset({(_exp_name(base, symbol), 1, 0)})})

    def factor(self) -> Cost:
        token = self.take()
        if token == "log":
            name = self.take()
            if not (name.isascii() and name.isalpha()) or name in ("log", "min", "max"):
                raise ValueError("log of a non-symbol")
            return frozenset({frozenset({(name, 0, 1)})})
        if token.isascii() and token.isdigit():
            return self.exponential(int(token))
        if token == "(":
            inner = self.expr()
            if self.take() != ")":
                raise ValueError("unbalanced")
            atom = inner
        elif token.isascii() and token.isalpha() and token not in ("min", "max"):
            atom = sym(token)
        else:
            raise ValueError(f"unsupported {token!r}")
        power = _SUPERSCRIPTS.get(self.peek() or "")
        if power:
            self.take()
            result = atom
            for _ in range(power - 1):
                result = mul(result, atom)
            return result
        return atom


def parse_label(label: str) -> Cost:
    if not (label.startswith("O(") and label.endswith(")")):
        raise ValueError(f"not a Big-O label: {label!r}")
    if label == "O(1)":
        return ONE
    return _LabelParser(label[2:-1]).parse()


def canonical_labels(pool: tuple[str, ...]) -> dict[Cost, str]:
    """cost -> first pool label with that canonical form; unparseable labels are skipped."""
    labels: dict[Cost, str] = {}
    for label in pool:
        try:
            labels.setdefault(parse_label(label), label)
        except ValueError:
            continue
    return labels

"""Expression half of the `complexity_infer` analyzer: sizes, values and expressions.

`ExprWalker` prices an expression as a `Pair` (time, space) and sizes iterables and magnitudes;
`complexity_calls.CallMixin` prices calls and `complexity_stmts.Analyzer` adds the statements.
"""
from __future__ import annotations

import ast
from dataclasses import replace

from complexity_calls import CallMixin
from complexity_cost import ONE, Cost, add, mul, sym
from complexity_model import (BUILDERS, CONTAINERS, ZERO, Abstain, Frame, Pair, Val, callee_name,
                              is_const, is_list_literal, mul_opt)

SAME_SIZE = frozenset("enumerate reversed sorted list set tuple frozenset iter".split())
COMPREHENSIONS = (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)
STRUCTURAL = (ast.BoolOp, ast.UnaryOp, ast.IfExp, ast.Tuple, ast.List, ast.Set, ast.Dict,
              ast.Attribute, ast.Starred, ast.JoinedStr, ast.FormattedValue)


class ExprWalker(CallMixin):
    def __init__(self, methods: dict, module_fns: dict, range_symbol: str | None,
                 shrunk: frozenset[str]) -> None:
        self.methods = methods
        self.module_fns = module_fns
        self.range_symbol = range_symbol
        self.shrunk = shrunk
        self.carried: frozenset[str] = frozenset()  # path-walk state the depth already counts
        self.heap_bounds: dict[str, Cost] = {}
        self.rec_sites: dict[str, list] = {}
        self.reasons: list[str] = []

    def guard(self, fn, *args) -> Pair:
        try:
            return fn(*args)
        except Abstain as stop:
            self.reasons.append(str(stop))
            return stop.pair()

    @staticmethod
    def fold(pairs) -> Pair:
        total = ZERO
        for p in pairs:
            total = total.then(p)
        return total

    def children(self, node: ast.AST, fr: Frame) -> Pair:
        return self.fold(self.expr(c, fr) for c in ast.iter_child_nodes(node)
                         if isinstance(c, ast.expr))

    # ── sizes and values ─────────────────────────────────────────────────────────
    def size_of(self, e: ast.expr, fr: Frame) -> Cost:
        if isinstance(e, ast.Name):
            val = fr.env.get(e.id)
            if val is not None and val.kind in CONTAINERS and val.size is not None:
                return val.size
            raise Abstain(f"unsized {e.id}")
        if isinstance(e, (ast.List, ast.Tuple, ast.Set, ast.Dict, ast.Constant)):
            return ONE
        if isinstance(e, COMPREHENSIONS):
            return self.comp_scope(e, fr)[0]
        if isinstance(e, ast.Subscript) and not isinstance(e.slice, ast.Slice):
            row = fr.env.get(e.value.id) if isinstance(e.value, ast.Name) else None
            if row is not None and row.inner is not None:
                return row.inner
        if isinstance(e, ast.Subscript) and isinstance(e.slice, ast.Slice):
            self.check_slice(e)
            return self.size_of(e.value, fr)
        if isinstance(e, ast.Call):
            name = callee_name(e)
            if name == "range":
                return self.range_size(e.args, fr)
            if name in SAME_SIZE and e.args:
                return self.size_of(e.args[0], fr)
            if name in ("items", "keys", "values") and isinstance(e.func, ast.Attribute):
                return self.size_of(e.func.value, fr)
        raise Abstain("cannot size")

    def range_size(self, args: list[ast.expr], fr: Frame) -> Cost:
        if not args or len(args) > 3 or (len(args) == 3 and not is_const(args[2])):
            raise Abstain("range shape")
        lo, hi = (ast.Constant(0), args[0]) if len(args) == 1 else (args[0], args[1])
        return self.mag(lo if is_const(hi) else hi, fr)

    @staticmethod
    def check_slice(e: ast.Subscript) -> None:
        for bound in (e.slice.lower, e.slice.upper, e.slice.step):
            if bound is not None and not is_const(bound):
                raise Abstain("variable slice bound")

    def value_range(self) -> Cost:
        if self.range_symbol is None:
            raise Abstain("value range needs __range__")
        return sym(self.range_symbol)

    def mag(self, e: ast.expr, fr: Frame) -> Cost:
        """Upper bound on the integer `e`: a bound symbol, a product or sum of them, or constant."""
        if is_const(e):
            return ONE
        if isinstance(e, ast.Name):
            val = fr.env.get(e.id)
            if val is not None and val.kind == "int" and val.size is not None:
                return val.size
            raise Abstain(f"unbound {e.id}")
        if isinstance(e, ast.UnaryOp):
            return self.mag(e.operand, fr)
        if isinstance(e, ast.BinOp):
            left, right = self.mag(e.left, fr), self.mag(e.right, fr)
            if isinstance(e.op, (ast.Add, ast.Sub)):
                return add(left, right)
            if isinstance(e.op, ast.Mult):
                return mul(left, right)
            if isinstance(e.op, (ast.FloorDiv, ast.Div, ast.RShift, ast.Mod)):
                return left
        if isinstance(e, ast.Subscript) and not isinstance(e.slice, ast.Slice):
            if isinstance(e.value, ast.Name) and getattr(fr.env.get(e.value.id), "kind", "") == "seq":
                return self.value_range()
        if isinstance(e, ast.Call):
            name, args = callee_name(e), e.args
            if name == "len" and len(args) == 1:
                return self.size_of(args[0], fr)
            if name in ("abs", "int") and len(args) == 1:
                return self.mag(args[0], fr)
            if name in ("min", "max"):
                if len(args) == 1:
                    return self.value_range()
                total = ONE
                for a in args:
                    total = add(total, self.mag(a, fr))
                return total
        raise Abstain("cannot bound")

    def infer_val(self, e: ast.expr, fr: Frame) -> Val | None:
        try:
            return self.val_of(e, fr)
        except Abstain:
            return None

    def val_of(self, e: ast.expr, fr: Frame) -> Val | None:
        if isinstance(e, ast.Name):
            return fr.env.get(e.id)
        if isinstance(e, ast.Constant):
            return Val("seq", ONE) if isinstance(e.value, str) else Val("int", ONE)
        shapes = {ast.Tuple: Val("seq", ONE), ast.List: Val("seq"), ast.Dict: Val("dict"),
                  ast.Set: Val("set")}
        if type(e) in shapes:
            return shapes[type(e)]
        if isinstance(e, COMPREHENSIONS):
            kind = {ast.SetComp: "set", ast.DictComp: "dict"}.get(type(e), "seq")
            return Val(kind, self.comp_scope(e, fr)[0])
        if isinstance(e, ast.BinOp) and self.repeated(e, fr) is not None:
            return Val("seq", self.repeated(e, fr))
        if isinstance(e, ast.Call):
            name = callee_name(e)
            if name == "range":
                return Val("seq", self.range_size(e.args, fr))
            kinds = {"list": "seq", "sorted": "seq", "tuple": "seq", "reversed": "seq",
                     "deque": "seq", "set": "set", "frozenset": "set", "Counter": "dict"}
            if name in kinds:
                return Val(kinds[name], self.size_of(e.args[0], fr) if e.args else None)
            if name in ("dict", "defaultdict", "OrderedDict"):
                return Val("dict")
        return Val("int", self.mag(e, fr))

    def repeated(self, e: ast.BinOp, fr: Frame) -> Cost | None:
        """Cells a `sequence * k` repetition builds; None when `e` is not a repetition."""
        if not isinstance(e.op, ast.Mult):
            return None
        for seq, k in ((e.left, e.right), (e.right, e.left)):
            is_text = isinstance(seq, ast.Constant) and isinstance(seq.value, str)
            if is_list_literal(seq) or is_text or self.is_container(seq, fr):
                return mul(self.size_of(seq, fr), self.mag(k, fr))
        return None

    def is_container(self, e: ast.expr, fr: Frame) -> bool:
        if isinstance(e, ast.Name):
            return getattr(fr.env.get(e.id), "kind", "") in CONTAINERS
        return isinstance(e, (ast.List, ast.Tuple, ast.ListComp, ast.SetComp, ast.DictComp,
                              ast.Dict, ast.Set))

    def retains_container(self, e: ast.expr, fr: Frame) -> bool:
        """Storing `e` keeps a container alive (so the store grows memory by more than one cell)."""
        if isinstance(e, ast.Name):
            return self.is_container(e, fr)
        return (isinstance(e, (ast.ListComp, ast.SetComp, ast.DictComp))
                or (isinstance(e, ast.Subscript) and isinstance(e.slice, ast.Slice))
                or (isinstance(e, ast.Call) and callee_name(e) in BUILDERS | {"copy"}))

    # ── expressions ──────────────────────────────────────────────────────────────
    def expr(self, e: ast.expr, fr: Frame) -> Pair:
        if isinstance(e, (ast.Constant, ast.Name)):
            return ZERO
        if isinstance(e, ast.Lambda):
            return self.lambda_(e, fr)
        if isinstance(e, ast.Call):
            return self.call(e, fr)
        if isinstance(e, COMPREHENSIONS):
            return self.comp(e, fr)
        if isinstance(e, ast.Compare):
            return self.compare(e, fr)
        if isinstance(e, ast.BinOp):
            return self.binop(e, fr)
        if isinstance(e, ast.Subscript):
            return self.subscript(e, fr)
        if isinstance(e, STRUCTURAL):
            return self.children(e, fr)
        raise Abstain(type(e).__name__)

    def lambda_(self, e: ast.Lambda, fr: Frame) -> Pair:
        child = replace(fr, env=dict(fr.env))
        for a in e.args.args:
            child.env.pop(a.arg, None)
        if self.expr(e.body, child) != ZERO:
            raise Abstain("non-constant lambda")
        return ZERO

    def subscript(self, e: ast.Subscript, fr: Frame) -> Pair:
        if not isinstance(e.slice, ast.Slice):
            return self.children(e, fr)
        self.check_slice(e)
        n = self.size_of(e.value, fr)
        return self.expr(e.value, fr).then(Pair(n, n))

    def binop(self, e: ast.BinOp, fr: Frame) -> Pair:
        kids = self.expr(e.left, fr).then(self.expr(e.right, fr))
        cells = self.repeated(e, fr)
        if cells is not None:
            return kids.then(Pair(cells, cells))
        if isinstance(e.op, ast.Add) and (self.is_container(e.left, fr) or self.is_container(e.right, fr)):
            raise Abstain("container concatenation")
        return kids

    def compare(self, e: ast.Compare, fr: Frame) -> Pair:
        total = self.children(e, fr)
        for op, right in zip(e.ops, e.comparators):
            if isinstance(op, (ast.In, ast.NotIn)):
                total = total.then(Pair(self.contains_cost(right, fr), ONE))
        return total

    def contains_cost(self, right: ast.expr, fr: Frame) -> Cost:
        if isinstance(right, ast.Name):
            val = fr.env.get(right.id)
            if val is not None and val.kind in ("set", "dict"):
                return ONE
            if val is not None and val.kind == "seq" and val.size is not None:
                return val.size
            raise Abstain(f"membership in unsized {right.id}")
        if isinstance(right, (ast.Constant, ast.List, ast.Tuple, ast.Set, ast.Dict, ast.SetComp,
                              ast.DictComp)):
            return ONE
        if isinstance(right, ast.Call) and callee_name(right) in ("set", "frozenset", "dict"):
            return ONE
        raise Abstain("membership in an unknown container")

    def bind_target(self, target: ast.expr, it: ast.expr, size: Cost | None, env: dict) -> None:
        source = env.get(it.id) if isinstance(it, ast.Name) else None
        for n in ast.walk(target):
            if isinstance(n, ast.Name):
                env.pop(n.id, None)
        counted = isinstance(it, ast.Call) and callee_name(it) in ("range", "enumerate")
        first = target.elts[0] if isinstance(target, ast.Tuple) and target.elts else target
        if counted and size is not None and isinstance(first, ast.Name):
            env[first.id] = Val("int", size)
        elif source is not None and source.inner is not None and isinstance(target, ast.Name):
            env[target.id] = Val("seq", source.inner, owned=False)

    def comp_scope(self, e: ast.expr, fr: Frame) -> tuple[Cost, Frame]:
        child = replace(fr, env=dict(fr.env))
        count = ONE
        for g in e.generators:
            size = self.size_of(g.iter, child)
            count = mul(count, size)
            self.bind_target(g.target, g.iter, size, child.env)
        return count, child

    def comp(self, e: ast.expr, fr: Frame) -> Pair:
        child = replace(fr, env=dict(fr.env))
        count, total = ONE, ZERO
        for g in e.generators:
            total = total.then(self.expr(g.iter, child).times(count))
            size = self.size_of(g.iter, child)
            count = mul(count, size)
            child = replace(child, loops=mul_opt(fr.loops, count))
            self.bind_target(g.target, g.iter, size, child.env)
            for cond in g.ifs:
                total = total.then(self.expr(cond, child).times(count))
        for part in ([e.key, e.value] if isinstance(e, ast.DictComp) else [e.elt]):
            total = total.then(self.expr(part, child).times(count))
        if isinstance(e, ast.GeneratorExp):
            return total
        return total.then(Pair(ONE, self.memory(e, fr)))

    def memory(self, e: ast.expr, fr: Frame) -> Cost:
        """Cells held by the fresh container `e` builds (scalars count one each)."""
        if isinstance(e, (ast.ListComp, ast.SetComp, ast.DictComp)):
            count, child = self.comp_scope(e, fr)
            return mul(count, self.memory(e.value if isinstance(e, ast.DictComp) else e.elt, child))
        if isinstance(e, ast.BinOp) and self.repeated(e, fr) is not None:
            return self.repeated(e, fr)
        if isinstance(e, ast.Subscript) and isinstance(e.slice, ast.Slice):
            return self.size_of(e.value, fr)
        if isinstance(e, ast.Call) and callee_name(e) in BUILDERS and e.args:
            return self.size_of(e.args[0], fr)
        return ONE

"""Static Big-O analyzer for the learner's own code: `infer` and `default_bind`.

    infer(source, entry, bind) -> {'time': label | None, 'space': label | None}

`entry` is a function or method name anywhere in `source`. `bind` maps an argument name to the
symbol that sizes it (`{"position": "n", "m": "m"}`): a sequence argument has length `n`, an int
argument has magnitude `m`. The key `"grid[]": "n"` sizes each row of the 2D argument `grid`
(its `bind` value `"m"` sizes `len(grid)`). The reserved key `"__range__": "R"` names the symbol for the value
range of the sequence elements (`position[-1] - position[0]`); a bisect over values needs it,
and without it the analyzer abstains. A label is always an exact member of the complexity pool
(or None = abstain on that axis); the two axes abstain independently.

Cost model, v1 and conservative. A cost is a sum of monomials over bound symbols and their logs
(`complexity_cost`). Statements add; a loop multiplies its body by its trip count; a `while`
costs log of its range only when it bisects (`mid = (lo + hi) // 2`, `lo`/`hi` moved to `mid`).
Space counts containers that grow with a symbol and sort scratch; the container the entry returns
is excluded, and a container that is also popped from is not sized. Recursion, an unknown call,
an unrecognised `while`, an unbound symbol, a slice with a variable bound, and anything else it
cannot size make that axis abstain.

The analyzer is split across `complexity_cost` (algebra), `complexity_model` (types),
`complexity_exprs` and `complexity_stmts`; `complexity_corpus` is the CLI. The pool is read from
`export_bigo.COMPLEXITY_POOL`; a host without `export_bigo` (the site's Pyodide) calls
`configure_pool(pool)` with the `pool` field of big-o.json first.

Stdlib only; no file I/O.
"""
from __future__ import annotations

import ast
import functools
import re

from complexity_cost import ONE, Cost, canonical_labels, sym
from complexity_model import RANGE_KEY, Frame, Val, param_kind
from complexity_stmts import Analyzer

SEQ_HEADS = frozenset({"List", "list", "str", "Sequence", "Tuple", "tuple"})
GRID_NAMES = ("grid", "board", "matrix", "mat")
EDGE_NAMES = ("edges", "prerequisites", "connections")
NODE_COUNT_NAMES = ("numCourses", "n", "numNodes", "N")
ROW_SUFFIX = "[]"  # bind key `grid[]`: the length of each row of the 2D argument `grid`
REMOVERS = frozenset({"pop", "popleft", "remove", "discard", "clear", "heappop"})
_pool_config: dict[str, tuple[str, ...]] = {}


def configure_pool(pool: list[str] | tuple[str, ...]) -> None:
    _pool_config["pool"] = tuple(pool)


@functools.lru_cache(maxsize=None)
def _labels(pool: tuple[str, ...]) -> dict[Cost, str]:
    return canonical_labels(pool)


def _label(cost: Cost | None) -> str | None:
    if cost is None:
        return None
    pool = _pool_config.get("pool")
    if pool is None:
        import export_bigo  # deferred: it pulls yaml, which the site does not load
        pool = export_bigo.COMPLEXITY_POOL
    return _labels(pool).get(cost)


def _locate(tree: ast.Module, entry: str):
    module_fns = {n.name: n for n in tree.body if isinstance(n, ast.FunctionDef)}
    for cls in (n for n in ast.walk(tree) if isinstance(n, ast.ClassDef)):
        methods = {m.name: m for m in cls.body if isinstance(m, ast.FunctionDef)}
        if entry in methods:
            return methods[entry], methods, module_fns
    found = next((n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == entry), None)
    return None if found is None else (found, {}, module_fns)


def _shrunk_names(tree: ast.AST) -> frozenset[str]:
    """Names a container is removed from anywhere (pop, remove, clear, del): its size is then
    not the count of appends, so growth of such a container is not inferred."""
    names: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and getattr(node.func, "attr", getattr(node.func, "id", None)) in REMOVERS:
            owner = node.func.value if isinstance(node.func, ast.Attribute) else None
            if not isinstance(owner, ast.Name) or owner.id == "heapq":
                owner = node.args[0] if node.args else None
            if isinstance(owner, ast.Name):
                names.add(owner.id)
        elif isinstance(node, ast.Delete):
            names |= {n.id for t in node.targets for n in ast.walk(t) if isinstance(n, ast.Name)}
    return frozenset(names)


def _returned_names(fn: ast.FunctionDef) -> frozenset[str]:
    """Names the entry returns directly (`return res`, `return a, b`): the output containers."""
    names: set[str] = set()
    for node in ast.walk(fn):
        if isinstance(node, ast.Return) and node.value is not None:
            value = node.value
            parts = value.elts if isinstance(value, ast.Tuple) else [value]
            names |= {p.id for p in parts if isinstance(p, ast.Name)}
    return frozenset(names)


def infer(source: str, entry: str, bind: dict[str, str]) -> dict[str, str | None]:
    """{'time': label | None, 'space': label | None}. None = abstain on that axis."""
    return analyze(source, entry, bind)[0]


def analyze(source: str, entry: str, bind: dict[str, str]) -> tuple[dict[str, str | None], list[str]]:
    """`infer` plus the reasons the analyzer gave up along the way (for the corpus report)."""
    abstained: dict[str, str | None] = {"time": None, "space": None}
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return abstained, ["syntax error"]
    located = _locate(tree, entry)
    if located is None:
        return abstained, ["entry not found"]
    fn, methods, module_fns = located
    env = {a.arg: Val(param_kind(a.annotation), sym(bind[a.arg]), owned=False,
                      inner=sym(bind[a.arg + ROW_SUFFIX]) if a.arg + ROW_SUFFIX in bind else None)
           for a in (*fn.args.args, *fn.args.kwonlyargs) if bind.get(a.arg)}
    frame = Frame(env, {}, (fn.name,), ONE, _returned_names(fn))
    analyzer = Analyzer(methods, module_fns, bind.get(RANGE_KEY), _shrunk_names(tree))
    result = analyzer.run_function(fn, frame)
    labels = {"time": _label(result.time), "space": _label(result.space)}  # run_function finished it
    if None in labels.values() and not analyzer.reasons:
        analyzer.reasons.append("no pool label")
    return labels, analyzer.reasons


def _split_params(text: str) -> list[str]:
    parts, depth, current = [], 0, ""
    for ch in text:
        depth += ch in "[("
        depth -= ch in "])"
        if ch == "," and depth == 0:
            parts.append(current)
            current = ""
        else:
            current += ch
    return [p.strip() for p in (*parts, current) if p.strip()]


def default_bind(signature: str, variables: dict[str, str]) -> dict[str, str]:
    """arg name -> symbol, from a spec signature and a bigo.yml `variables` map: an int argument
    named like a variable binds to it; the single flat List/str argument binds to `n`, or to `k`
    when a grid already took `n`."""
    bind: dict[str, str] = {}
    sequences: list[str] = []
    grids: list[str] = []
    for param in _split_params(signature.rsplit("->", 1)[0]):
        name, _, annotation = param.partition(":")
        name, annotation = name.strip(), annotation.partition("=")[0].strip()
        head = (re.match(r"\w+", annotation) or re.match(r"", "")).group()
        nested = re.match(r"\w+\[\s*(List|list)\b", annotation)
        if head == "int" and name in variables:
            bind[name] = name
        elif head == "int" and "V" in variables and name in NODE_COUNT_NAMES:
            bind[name] = "V"
        elif head in SEQ_HEADS and nested and name in EDGE_NAMES and "E" in variables:
            bind[name] = "E"
        elif head in SEQ_HEADS and nested:
            grids.append(name)
        elif head in SEQ_HEADS:
            sequences.append(name)
    chosen = [g for g in grids if g in GRID_NAMES] or (grids if len(grids) == 1 else [])
    if "m" in variables and "n" in variables and len(chosen) == 1:
        bind[chosen[0]], bind[chosen[0] + ROW_SUFFIX] = "m", "n"
    if "n" in variables and len(sequences) == 1 and "n" not in bind.values():
        bind[sequences[0]] = "n"
    elif "n" in bind.values() and "k" in variables and "k" not in bind.values() and len(sequences) == 1:
        bind[sequences[0]] = "k"  # the grid took n, so the one sequence left is the pattern's length
    return bind


if __name__ == "__main__":
    from complexity_corpus import main
    main()

"""Syntax tests for the `while` shapes `complexity_infer` can price.

A pointer loop (`while l < r`, `while r < len(x)`) costs the pointers' range when every path
through its body steps a pointer toward the bound by a positive constant and nothing moves a
pointer any other way. A sliding window's inner `while` costs its total steps once: its pointer
is stepped only there, so across the outer loop it cannot pass its range.
"""
from __future__ import annotations

import ast

MUTATORS = frozenset("append appendleft pop popleft extend insert remove clear add discard "
                     "update sort reverse".split())


def _is_step(s: ast.AST, name: str, direction: int) -> bool:
    """`name += c` / `name -= c` / `name = name +- c` moving `direction` (+1 up, -1 down) by c > 0."""
    if isinstance(s, ast.AugAssign):
        target, op, amount = s.target, s.op, s.value
    elif (isinstance(s, ast.Assign) and len(s.targets) == 1 and isinstance(s.value, ast.BinOp)
          and isinstance(s.value.left, ast.Name) and s.value.left.id == name):
        target, op, amount = s.targets[0], s.value.op, s.value.right
    else:
        return False
    moves = isinstance(op, ast.Add) if direction > 0 else isinstance(op, ast.Sub)
    return (isinstance(target, ast.Name) and target.id == name and moves
            and isinstance(amount, ast.Constant) and isinstance(amount.value, int)
            and amount.value > 0)


def _steps_any(s: ast.AST, steps: dict[str, int]) -> bool:
    return any(_is_step(s, name, direction) for name, direction in steps.items())


def all_stores_are_steps(roots: list[ast.AST], steps: dict[str, int]) -> bool:
    """Every assignment to a tracked name under `roots` is one of its legal steps."""
    nodes = [n for root in roots for n in ast.walk(root)]
    stores = sum(1 for n in nodes if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store)
                 and n.id in steps)
    return stores == sum(1 for n in nodes if _steps_any(n, steps))


def every_path_steps(body: list[ast.stmt], steps: dict[str, int]) -> bool:
    """Each path from the top of `body` steps a tracked name (or leaves the loop) first."""
    for s in body:
        if _steps_any(s, steps) or isinstance(s, (ast.Break, ast.Return, ast.Raise)):
            return True
        if (isinstance(s, ast.If) and s.orelse and every_path_steps(s.body, steps)
                and every_path_steps(s.orelse, steps)):
            return True
    return False


def has_continue(body: list[ast.stmt]) -> bool:
    return any(isinstance(n, ast.Continue) for s in body for n in ast.walk(s))


def bound_is_stable(bound: ast.expr, body: list[ast.stmt]) -> bool:
    """Nothing in `body` rebinds or resizes a name the bound mentions."""
    names = {n.id for n in ast.walk(bound) if isinstance(n, ast.Name)}
    for stmt in body:
        for n in ast.walk(stmt):
            if isinstance(n, ast.Name) and isinstance(n.ctx, (ast.Store, ast.Del)) and n.id in names:
                return False
            if (isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute)
                    and n.func.attr in MUTATORS and isinstance(n.func.value, ast.Name)
                    and n.func.value.id in names):
                return False
    return True


def pointer_steps(test: ast.expr, body: list[ast.stmt]) -> tuple[ast.expr, ast.expr] | None:
    """(pointer, bound) of a `while p < bound` / `while p <= bound` loop whose every path steps
    `p` up (or the bound down, when the bound is itself a pointer) and moves nothing back."""
    if not (isinstance(test, ast.Compare) and len(test.ops) == 1
            and isinstance(test.ops[0], (ast.Lt, ast.LtE)) and isinstance(test.left, ast.Name)):
        return None
    pointer, bound = test.left, test.comparators[0]
    steps = {pointer.id: 1}
    if isinstance(bound, ast.Name) and any(
            isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store) and n.id == bound.id
            for s in body for n in ast.walk(s)):
        steps[bound.id] = -1
    elif not bound_is_stable(bound, body):
        return None
    if (has_continue(body) or not all_stores_are_steps(body, steps)
            or not every_path_steps(body, steps)):
        return None
    return pointer, bound


def amortized_pointer(loop: ast.While, owner: ast.AST) -> str | None:
    """A name every path through `loop` steps up and that nothing else under `owner` changes."""
    if has_continue(loop.body):
        return None
    candidates = sorted({n.target.id for s in loop.body for n in ast.walk(s)
                         if isinstance(n, ast.AugAssign) and isinstance(n.target, ast.Name)})
    for name in candidates:
        steps = {name: 1}
        if every_path_steps(loop.body, steps) and all_stores_are_steps([owner], steps):
            return name
    return None

"""Shared types and syntax helpers for the `complexity_infer` analyzer.

`Pair` is the (time, space) cost of a piece of code (None = that axis abstained), `Abstain` is
raised where the analyzer cannot tell, `Val` is what a name holds, and `Frame` is one call's scope.
Stdlib only: the site runs this in Pyodide.
"""
from __future__ import annotations

import ast
import re
from dataclasses import dataclass

from complexity_cost import ONE, Cost, add, log_of_cost, mul

RANGE_KEY = "__range__"
BOTH = ("time", "space")
CONTAINERS = frozenset({"seq", "set", "dict"})
SELF_NAMES = ("self", "cls")
BUILDERS = frozenset("list sorted set frozenset dict tuple reversed Counter deque".split())


def add_opt(a: Cost | None, b: Cost | None) -> Cost | None:
    return None if a is None or b is None else add(a, b)


def mul_opt(a: Cost | None, b: Cost | None) -> Cost | None:
    return None if a is None or b is None else mul(a, b)


@dataclass(frozen=True)
class Pair:
    """`once` is time that does not repeat with the loops around it: an inner `while` whose
    pointer only moves forward costs its total steps once, not per outer iteration. The loop
    that owns the pointer folds it into `time` with `settled`."""
    time: Cost | None = ONE
    space: Cost | None = ONE
    once: Cost | None = ONE
    last: Cost | None = ONE

    def then(self, other: Pair) -> Pair:
        return Pair(add_opt(self.time, other.time), add_opt(self.space, other.space),
                    add_opt(self.once, other.once), add_opt(self.last, other.last))

    def times(self, trips: Cost | None) -> Pair:
        """Repeat for `trips` iterations: time multiplies, space (freed each round) does not."""
        return Pair(mul_opt(trips, self.time), self.space, self.once, self.last)

    def settled(self) -> Pair:
        return Pair(add_opt(self.time, self.once), self.space, ONE, self.last)

    def finished(self) -> Pair:
        """A whole call: `last`, the time of its `return`, runs once however many loops wrap it."""
        return Pair(add_opt(add_opt(self.time, self.once), self.last), self.space)


ZERO = Pair()


class Abstain(Exception):
    def __init__(self, reason: str, axes: tuple[str, ...] = BOTH) -> None:
        super().__init__(reason)
        self.axes = axes

    def pair(self) -> Pair:
        return Pair(None if "time" in self.axes else ONE, None if "space" in self.axes else ONE)


def is_linear(cost: Cost) -> bool:
    """Constant, or a single symbol to the first power."""
    if cost == ONE:
        return True
    return len(cost) == 1 and all(len(m) == 1 and next(iter(m))[1:] == (1, 0) for m in cost)


def log_cost(cost: Cost) -> Cost:
    try:
        return log_of_cost(cost)
    except ValueError as exc:
        raise Abstain("log of a non-linear size") from exc


@dataclass(frozen=True)
class Val:
    """What a name holds: `kind` seq/set/dict (size = length) or int (size = magnitude);
    `inner` is the length of each element of a 2D sequence (a grid's columns)."""
    kind: str
    size: Cost | None = None
    owned: bool = True
    inner: Cost | None = None


@dataclass(frozen=True)
class Frame:
    """`env` and `fns` are shared and mutated in program order (a flow-insensitive upper bound);
    `loops` is the product of the trip counts around the current statement within this call;
    `inner` and `owner` are the trip count and node of the innermost enclosing loop."""
    env: dict
    fns: dict
    stack: tuple
    loops: Cost | None
    outputs: frozenset
    inner: Cost | None = None
    owner: object = None


def is_const(e: ast.AST) -> bool:
    if isinstance(e, ast.UnaryOp) and isinstance(e.op, (ast.USub, ast.UAdd)):
        e = e.operand
    return isinstance(e, ast.Constant)


def callee_name(call: ast.Call) -> str | None:
    func = call.func
    return func.id if isinstance(func, ast.Name) else func.attr if isinstance(func, ast.Attribute) else None


def is_list_literal(e: ast.AST) -> bool:
    return isinstance(e, (ast.List, ast.Tuple))


def is_num(e: ast.AST, value: int) -> bool:
    return isinstance(e, ast.Constant) and e.value == value


def param_kind(annotation: ast.AST | None) -> str:
    head = re.match(r"\w+", ast.unparse(annotation)) if annotation is not None else None
    name = head.group() if head else ""
    if name in ("int", "float"):
        return "int"
    if name in ("dict", "Dict", "Counter", "defaultdict", "Mapping"):
        return "dict"
    return "set" if name in ("set", "Set", "frozenset", "FrozenSet") else "seq"


def builds_value(e: ast.AST) -> bool:
    return (isinstance(e, (ast.ListComp, ast.SetComp, ast.DictComp, ast.List, ast.Dict,
                           ast.Set, ast.Tuple, ast.BinOp))
            or (isinstance(e, ast.Subscript) and isinstance(e.slice, ast.Slice))
            or (isinstance(e, ast.Call) and callee_name(e) in BUILDERS))


def assigned_names(node: ast.AST) -> list[str]:
    if isinstance(node, ast.Assign):
        targets = node.targets
    elif isinstance(node, (ast.AugAssign, ast.AnnAssign)):
        targets = [node.target]
    else:
        return []
    return [n.id for t in targets for n in ast.walk(t) if isinstance(n, ast.Name)]


def _is_midpoint(v: ast.AST, lo: str, hi: str) -> bool:
    nodes = list(ast.walk(v))
    names = {n.id for n in nodes if isinstance(n, ast.Name)}
    halves = any(isinstance(n, ast.BinOp) and (
        (isinstance(n.op, ast.FloorDiv) and is_num(n.right, 2))
        or (isinstance(n.op, ast.RShift) and is_num(n.right, 1))) for n in nodes)
    plain = all(isinstance(n, (ast.BinOp, ast.Name, ast.Constant, ast.Add, ast.Sub,
                               ast.FloorDiv, ast.RShift, ast.Load)) for n in nodes)
    return names == {lo, hi} and halves and plain


def _moves_to_mid(v: ast.AST, mids: set[str]) -> bool:
    if isinstance(v, ast.Name):
        return v.id in mids
    return (isinstance(v, ast.BinOp) and isinstance(v.op, (ast.Add, ast.Sub))
            and isinstance(v.left, ast.Name) and v.left.id in mids and is_const(v.right))


def is_bisect_body(body: list[ast.stmt], lo: str, hi: str) -> bool:
    """The loop computes `mid` from `lo`/`hi` and only ever moves `lo` and `hi` to `mid` (+-const)."""
    nodes = [n for stmt in body for n in ast.walk(stmt)]
    mids = {n.targets[0].id for n in nodes if isinstance(n, ast.Assign) and len(n.targets) == 1
            and isinstance(n.targets[0], ast.Name) and _is_midpoint(n.value, lo, hi)}
    moved: set[str] = set()
    for n in nodes:
        for name in {lo, hi} & set(assigned_names(n)):
            simple = (isinstance(n, ast.Assign) and len(n.targets) == 1
                      and isinstance(n.targets[0], ast.Name) and _moves_to_mid(n.value, mids))
            if not simple:
                return False
            moved.add(name)
    return bool(mids) and moved == {lo, hi}

"""Syntax rules for path-walking recursion in `complexity_infer` (a grid word search, a path DFS).

A recursion that passes a growing path `p` down unchanged (`p.append(..)` before the sites,
`p.pop()` after, `len(p)` compared with a bound size) is as deep as that size, and with b flat
sites it takes b^depth calls. Everything here reads syntax only; sizes come from the analyzer.
Stdlib only: the site runs this in Pyodide.
"""
from __future__ import annotations

import ast

from complexity_model import SELF_NAMES, callee_name

GRID_MOVES = 4
GRID_BASE = 3  # one of the four directions is the cell just left, which `visited` rejects
UNIT_STEP = {ast.Add: 1, ast.Sub: -1}


def recursive_calls(f: ast.FunctionDef) -> list[tuple[ast.Call, bool]]:
    """Every call in `f` to `f` itself, with whether it goes through `self`."""
    calls = [n for n in ast.walk(f) if isinstance(n, ast.Call) and callee_name(n) == f.name]
    return [(c, isinstance(c.func, ast.Attribute)
             and isinstance(c.func.value, ast.Name) and c.func.value.id in SELF_NAMES)
            for c in calls]


def given_args(f: ast.FunctionDef, call: ast.Call, skip_self: bool) -> dict[str, ast.expr]:
    params = [a.arg for a in f.args.args][1 if skip_self else 0:]
    given = dict(zip(params, call.args))
    given.update({k.arg: k.value for k in call.keywords if k.arg})
    return given


def _is_name(e: ast.AST | None, name: str) -> bool:
    return isinstance(e, ast.Name) and e.id == name


def passed_unchanged(f: ast.FunctionDef) -> frozenset[str]:
    """Parameters every recursive call passes as the bare name."""
    calls = recursive_calls(f)
    if not calls:
        return frozenset()
    givens = [given_args(f, call, skip) for call, skip in calls]
    return frozenset(a.arg for a in f.args.args if all(_is_name(g.get(a.arg), a.arg) for g in givens))


def _method_receivers(f: ast.FunctionDef, method: str) -> list[tuple[str, ast.Call]]:
    return [(n.func.value.id, n) for n in ast.walk(f)
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute)
            and n.func.attr == method and isinstance(n.func.value, ast.Name)]


def _grows_before(f: ast.FunctionDef, param: str, line: int) -> bool:
    """`param` was appended to above `line` with no `param.pop()` since (by source order)."""
    appends = [c.lineno for name, c in _method_receivers(f, "append") if name == param and c.lineno < line]
    pops = [c.lineno for name, c in _method_receivers(f, "pop") if name == param]
    return bool(appends) and not any(max(appends) < p < line for p in pops)


def path_params(f: ast.FunctionDef) -> frozenset[str]:
    """Parameters passed unchanged at every recursive call, with the path grown before each call."""
    lines = [call.lineno for call, _ in recursive_calls(f)]
    return frozenset(p for p in passed_unchanged(f) if all(_grows_before(f, p, n) for n in lines))


def carried_params(f: ast.FunctionDef) -> frozenset[str]:
    """The state a path walk carries down (path, visited): its growth is counted by the depth."""
    return passed_unchanged(f) if path_params(f) else frozenset()


def len_compared(f: ast.FunctionDef, param: str) -> list[ast.expr]:
    """The other side of each `len(param) ==/>=/> x` comparison in `f`."""
    others: list[ast.expr] = []
    for node in ast.walk(f):
        if not (isinstance(node, ast.Compare) and len(node.ops) == 1
                and isinstance(node.ops[0], (ast.Eq, ast.GtE, ast.Gt))):
            continue
        for side, other in ((node.left, node.comparators[0]), (node.comparators[0], node.left)):
            if (isinstance(side, ast.Call) and callee_name(side) == "len" and len(side.args) == 1
                    and _is_name(side.args[0], param)):
                others.append(other)
    return others


def _unit_step(arg: ast.expr | None, param: str) -> int | None:
    """+1 / -1 for `param + 1` / `param - 1`, else None."""
    if (isinstance(arg, ast.BinOp) and type(arg.op) in UNIT_STEP and _is_name(arg.left, param)
            and isinstance(arg.right, ast.Constant) and arg.right.value == 1):
        return UNIT_STEP[type(arg.op)]
    return None


def _grid_moves(f: ast.FunctionDef) -> set[tuple[str, int]] | None:
    """The `(param, +-1)` move of each recursive call, or None when a call is not one unit step
    of a single parameter."""
    moves: set[tuple[str, int]] = set()
    for call, skip in recursive_calls(f):
        given = given_args(f, call, skip)
        stepped = {p: s for p, s in ((p, _unit_step(a, p)) for p, a in given.items()) if s}
        if len(stepped) != 1:
            return None
        moves.update(stepped.items())
    return moves


def _cell_names(e: ast.expr, cells: set[str]) -> bool:
    """`e` is the tuple `(r, c)` over exactly the two cell params."""
    return (isinstance(e, ast.Tuple) and len(e.elts) == len(cells)
            and {x.id for x in e.elts if isinstance(x, ast.Name)} == cells)


def _rejects_visited(f: ast.FunctionDef, cells: set[str], visited: str) -> bool:
    """An `if` whose test has `(r, c) in visited` and whose body returns."""
    for node in ast.walk(f):
        if not (isinstance(node, ast.If)
                and any(isinstance(n, ast.Return) for s in node.body for n in ast.walk(s))):
            continue
        for test in (n for n in ast.walk(node.test) if isinstance(n, ast.Compare)):
            if (isinstance(test.ops[0], ast.In) and _is_name(test.comparators[0], visited)
                    and _cell_names(test.left, cells)):
                return True
    return False


def _marks_visited(f: ast.FunctionDef, cells: set[str], visited: str, first_site: int) -> bool:
    """`visited.add((r, c))` before the first recursive call."""
    return any(name == visited and call.lineno < first_site and call.args
               and _cell_names(call.args[0], cells)
               for name, call in _method_receivers(f, "add"))


def is_grid_visited(f: ast.FunctionDef) -> bool:
    """Four unit moves of two int params `r`, `c` (the other passed bare), `(r, c) in v` rejected
    and `v.add((r, c))` done before the calls, `v` passed down unchanged: a self-avoiding walk."""
    calls = recursive_calls(f)
    moves = _grid_moves(f)
    if len(calls) != GRID_MOVES or moves is None or len(moves) != GRID_MOVES:
        return False
    cells = {param for param, _ in moves}
    if len(cells) != 2 or any((p, s) not in moves for p in cells for s in (1, -1)):
        return False
    for call, skip in calls:
        given = given_args(f, call, skip)
        if not all(_is_name(given.get(p), p) or _unit_step(given.get(p), p) for p in cells):
            return False
    first_site = min(call.lineno for call, _ in calls)
    return any(_rejects_visited(f, cells, v) and _marks_visited(f, cells, v, first_site)
               for v in passed_unchanged(f) - cells)

"""Statement half of the `complexity_infer` analyzer.

A loop multiplies its body's time by its trip count; a `while` costs log of its range when it
bisects and its pointers' range when it only steps forward (`complexity_loops`). Space is never
multiplied by a loop, except what a container grows by inside it (`Frame.loops` scales that). The
container the entry returns is excluded from space. A recursive function costs its depth in
space, and in time only when it calls itself once, outside any loop; a path walk
(`complexity_paths`) with several flat sites costs base^depth.
"""
from __future__ import annotations

import ast
from dataclasses import replace

from complexity_cost import ONE, Cost, add, exp_of_cost
from complexity_exprs import ExprWalker
from complexity_loops import amortized_pointer, pointer_steps
from complexity_model import (CONTAINERS, ZERO, Abstain, Frame, Pair, Val, add_opt, builds_value,
                              is_bisect_body, is_const, log_cost, mul_opt)
from complexity_paths import (GRID_BASE, carried_params, is_grid_visited, len_compared,
                              path_params)

NO_COST_STMTS = (ast.Pass, ast.Break, ast.Continue, ast.Import, ast.ImportFrom, ast.Global,
                 ast.Nonlocal, ast.Delete)


class Analyzer(ExprWalker):
    def run_function(self, f: ast.FunctionDef, frame: Frame) -> Pair:
        """Price `f`'s body in `frame`, then price any recursion into itself."""
        outer, self.carried = self.carried, carried_params(f)
        try:
            body = self.stmts(f.body, frame)
        finally:
            self.carried = outer
        sites = self.rec_sites.pop(f.name, [])
        priced = body.finished()
        return self.recurse(f, priced, sites) if sites else priced

    def recurse(self, f: ast.FunctionDef, body: Pair, sites: list) -> Pair:
        try:
            path = self.path_depth(f, sites)
            depth = path if path is not None else self.recursion_depth(f, sites)
        except Abstain as stop:
            self.reasons.append(str(stop))
            return Pair(None, None)
        time = self.recursion_time(f, body, sites, depth, path is not None)
        return Pair(time, depth if body.space == ONE else None)

    def recursion_time(self, f: ast.FunctionDef, body: Pair, sites: list, depth: Cost,
                       is_path: bool) -> Cost | None:
        """One flat site costs depth x body; b flat sites of a path walk cost body x base^depth."""
        if len(sites) == 1 and sites[0].flat:
            return mul_opt(depth, body.time)
        if not is_path or len(sites) < 2 or not all(s.flat for s in sites):
            return None
        if f.decorator_list:
            self.reasons.append("memoized recursion is not exponential")
            return None
        base = GRID_BASE if is_grid_visited(f) else len(sites)
        try:
            return mul_opt(body.time, exp_of_cost(base, depth))
        except ValueError:
            self.reasons.append("recursion depth is not a single symbol")
            return None

    def path_depth(self, f: ast.FunctionDef, sites: list) -> Cost | None:
        """The size a passed-down path is capped at (`len(path) == len(word)`), or None."""
        for param in sorted(path_params(f)):
            caps = {self.len_cap(f, param, Frame(site.env, {}, (), ONE, frozenset()))
                    for site in sites}
            if len(caps) == 1 and None not in caps:
                return caps.pop()
        return None

    def len_cap(self, f: ast.FunctionDef, param: str, frame: Frame) -> Cost | None:
        for other in len_compared(f, param):
            try:
                cap = self.mag(other, frame)
            except Abstain:
                continue
            if cap != ONE:
                return cap
        return None

    def recursion_depth(self, f: ast.FunctionDef, sites: list) -> Cost:
        """How deep the recursion goes: the index limit of a `p + c` parameter, or the size of
        the bound tree/list a parameter walks down with `p.attr`."""
        depths = {self.site_depth(f, site) for site in sites}
        if len(depths) != 1:
            raise Abstain("recursion depths differ")
        return depths.pop()

    def site_depth(self, f: ast.FunctionDef, site) -> Cost:
        params = [a.arg for a in f.args.args][1 if site.skip_self else 0:]
        given = dict(zip(params, site.call.args))
        given.update({k.arg: k.value for k in site.call.keywords if k.arg})
        frame = Frame(site.env, {}, (), ONE, frozenset())
        for param, arg in given.items():
            if (isinstance(arg, ast.BinOp) and isinstance(arg.op, ast.Add)
                    and isinstance(arg.left, ast.Name) and arg.left.id == param
                    and is_const(arg.right)):
                cap = self.index_cap(f, param, frame)
                if cap is not None:
                    return cap
            if (isinstance(arg, ast.Attribute) and isinstance(arg.value, ast.Name)
                    and arg.value.id == param):
                val = site.env.get(param)
                if val is not None and val.kind == "seq" and val.size is not None:
                    return val.size
        raise Abstain("recursion depth is not bounded by a bound symbol")

    def index_cap(self, f: ast.FunctionDef, param: str, frame: Frame) -> Cost | None:
        """What `param` is compared with in `f` (`i == len(x)`, `i >= n`), if that is bound."""
        for node in ast.walk(f):
            if not isinstance(node, ast.Compare):
                continue
            sides = [node.left, *node.comparators]
            if not any(isinstance(s, ast.Name) and s.id == param for s in sides):
                continue
            for side in sides:
                if isinstance(side, ast.Name) and side.id == param:
                    continue
                try:
                    cap = self.mag(side, frame)
                except Abstain:
                    continue
                if cap != ONE:
                    return cap
        return None

    def stmts(self, body: list[ast.stmt], fr: Frame) -> Pair:
        total = ZERO
        for s in body:
            total = total.then(self.guard(self.stmt, s, fr))
        return total

    def stmt(self, s: ast.stmt, fr: Frame) -> Pair:
        if isinstance(s, NO_COST_STMTS):
            return ZERO
        if isinstance(s, ast.Expr):
            return self.expr(s.value, fr)
        if isinstance(s, ast.Assign):
            return self.assign(s.targets, s.value, fr)
        if isinstance(s, ast.AnnAssign):
            return self.assign([s.target], s.value, fr) if s.value else ZERO
        if isinstance(s, ast.AugAssign):
            return self.aug_assign(s, fr)
        if isinstance(s, ast.Return):
            return self.ret(s, fr)
        if isinstance(s, ast.If):
            return (self.guard(self.expr, s.test, fr).then(self.stmts(s.body, fr))
                    .then(self.stmts(s.orelse, fr)))
        if isinstance(s, ast.For):
            return self.for_(s, fr)
        if isinstance(s, ast.While):
            return self.while_(s, fr)
        if isinstance(s, ast.With):
            head = self.fold(self.guard(self.expr, item.context_expr, fr) for item in s.items)
            return head.then(self.stmts(s.body, fr))
        if isinstance(s, ast.Try):
            parts = [s.body, *(h.body for h in s.handlers), s.orelse, s.finalbody]
            return self.fold(self.stmts(p, fr) for p in parts)
        if isinstance(s, (ast.Assert, ast.Raise)):
            return self.children(s, fr)
        if isinstance(s, ast.FunctionDef):
            fr.fns[s.name] = s
            return ZERO
        raise Abstain(type(s).__name__)

    def assign(self, targets: list[ast.expr], value: ast.expr, fr: Frame) -> Pair:
        cost = self.guard(self.expr, value, fr)
        bindings = [b for t in targets for b in self.bindings(t, value, fr)]
        for name, val in bindings:
            fr.env.pop(name, None)
            if val is not None:
                fr.env[name] = val
        for t in targets:
            cost = cost.then(self.guard(self.store, t, value, fr))
        names = {x.id for t in targets for x in ast.walk(t) if isinstance(x, ast.Name)}
        if names and names <= fr.outputs:
            return Pair(cost.time, ONE, cost.once)
        return cost

    def bindings(self, target: ast.expr, value: ast.expr, fr: Frame) -> list[tuple[str, Val | None]]:
        if isinstance(target, ast.Name):
            return [(target.id, self.infer_val(value, fr))]
        if isinstance(target, ast.Tuple):
            if isinstance(value, ast.Tuple) and len(value.elts) == len(target.elts):
                return [b for t, v in zip(target.elts, value.elts) for b in self.bindings(t, v, fr)]
            return [(n.id, None) for n in ast.walk(target) if isinstance(n, ast.Name)]
        return []

    def store(self, t: ast.expr, value: ast.expr, fr: Frame) -> Pair:
        if isinstance(t, ast.Attribute):
            return Pair(ONE, None) if self.retains_container(value, fr) else ZERO
        if not isinstance(t, ast.Subscript):
            return ZERO
        root = t
        while isinstance(root, ast.Subscript):
            root = root.value
        if not isinstance(root, ast.Name):
            raise Abstain("store target", ("space",))
        reach = self.children(t, fr)
        val = fr.env.get(root.id)
        if val is None:
            return reach.then(Pair(ONE, None))
        if val.kind in ("dict", "set"):
            return reach.then(Pair(ONE, self.growth(root.id, val, ONE, fr, (value,))))
        return reach

    def aug_assign(self, s: ast.AugAssign, fr: Frame) -> Pair:
        cost = self.guard(self.expr, s.value, fr)
        if isinstance(s.target, ast.Name):
            val = fr.env.get(s.target.id)
            if val is not None and val.kind in CONTAINERS:
                raise Abstain("in-place container update")
            fr.env.pop(s.target.id, None)
            return cost
        stored = cost.then(self.store(s.target, s.value, fr))
        root = s.target
        while isinstance(root, ast.Subscript):
            root = root.value
        counter = fr.env.get(root.id) if isinstance(root, ast.Name) else None
        if counter is not None and counter.kind == "dict":
            return stored.then(Pair(ONE, None))  # a counter's key count is the alphabet, not the loop
        return stored

    def ret(self, s: ast.Return, fr: Frame) -> Pair:
        """A return runs once per call: its time goes to `last`, and its built value is output."""
        if s.value is None:
            return ZERO
        cost = self.expr(s.value, fr)
        space = ONE if builds_value(s.value) else cost.space
        return Pair(ONE, space, cost.once, add_opt(cost.time, cost.last))

    def for_(self, s: ast.For, fr: Frame) -> Pair:
        head = self.guard(self.expr, s.iter, fr)
        try:
            trips: Cost | None = self.size_of(s.iter, fr)
        except Abstain as stop:
            self.reasons.append(str(stop))
            trips = None
        self.bind_target(s.target, s.iter, trips, fr.env)
        body = self.stmts(s.body, replace(fr, loops=mul_opt(fr.loops, trips), inner=trips, owner=s))
        return head.then(body.times(trips).settled()).then(self.stmts(s.orelse, fr))

    def while_(self, s: ast.While, fr: Frame) -> Pair:
        head = self.guard(self.expr, s.test, fr)
        try:
            trips: Cost | None = self.while_trips(s, fr)
        except Abstain as stop:
            if self.is_amortized(s, fr):
                return self.amortized_while(s, head, fr)
            self.reasons.append(str(stop))
            trips = None
        body = self.stmts(s.body, replace(fr, loops=mul_opt(fr.loops, trips), inner=trips, owner=s))
        return head.then(body.times(trips).settled()).then(self.stmts(s.orelse, fr))

    def while_trips(self, s: ast.While, fr: Frame) -> Cost:
        shape = pointer_steps(s.test, s.body)
        if shape is not None:
            return add(self.mag(shape[0], fr), self.mag(shape[1], fr))
        return self.bisect_trips(s, fr)

    def is_amortized(self, s: ast.While, fr: Frame) -> bool:
        """A sliding window's inner `while`: its pointer starts at a constant, steps only here,
        and so moves at most as far as the enclosing loop's range."""
        if fr.owner is None or fr.inner is None:
            return False
        pointer = amortized_pointer(s, fr.owner)
        start = fr.env.get(pointer) if pointer else None
        return start is not None and start.kind == "int" and start.size == ONE

    def amortized_while(self, s: ast.While, head: Pair, fr: Frame) -> Pair:
        body = self.stmts(s.body, fr)
        steps = mul_opt(fr.inner, add_opt(head.time, body.time))
        return Pair(head.time, body.space, add_opt(steps, body.once), body.last)

    @staticmethod
    def bisect_trips(s: ast.While, fr: Frame) -> Cost:
        test = s.test
        if not (isinstance(test, ast.Compare) and len(test.ops) == 1
                and isinstance(test.ops[0], (ast.Lt, ast.LtE)) and isinstance(test.left, ast.Name)
                and isinstance(test.comparators[0], ast.Name)):
            raise Abstain("while is not a bisect", ("time",))
        lo, hi = test.left.id, test.comparators[0].id
        if not is_bisect_body(s.body, lo, hi):
            raise Abstain("while is not a bisect", ("time",))
        sizes = [fr.env.get(name) for name in (lo, hi)]
        if any(v is None or v.kind != "int" or v.size is None for v in sizes):
            raise Abstain("bisect bounds are unbound", ("time",))
        return log_cost(add(sizes[0].size, sizes[1].size))
